import sys
from math import sqrt as s, sqrt

def find_shrinker(n, xs, ys):
    dp = dict()
    def dp1(i, x, y):
        if i == len(xs) or (x, y) in dp:
            return dp[x, y]
        px, py = x, y
        while x - py > 0 and y - px > 0 and (x >= y):
            px, py = x - px, y - py
        xi, yi = x - px, y - py
        res = i / s((xi, yi)) / 2
        dp[i, (x,y)] = res
        return res
    for k in range(n // 2):
        for i in range(k + 1, n):
            res = 0
            for j1 in range(min(n, k + i)):
                x1, y1 = xs[0], ys[0]
                for j in range(1, i + 1):
                    x1, y1 = x1 + dp1(k, xs[i - j], ys[i - j]), y1 + dp1(k, x1, y1)
                res = max(res, x1)
            for j2 in range(max(k, n - i)):
                x2, y2 = xs[i], ys[i]
                for j in range(1, n - i):
                    x2, y2 = x2 + dp1(k, xs[i + j], ys[i + j]), y2 + dp1(k, x2, y2)
                res = max(res, y2)
            dp1(i, x1, y1) = res + dp1(i - 1, x2, y2) / s(2) if res + dp1(i - 1, x2, y2) > dp1(i, x1, y1) else dp1(i, x1, y1)
            dp1(i, x2, y2) = dp1(i - 1, x1, y1) / s(2) if res + dp1(i - 1, x2, y2) > dp1(i, x2, y2) else dp1(i, x2, y2)
    return dp[n - 1]

