import re

def parse_rules(rules):
    rules_dict = {}
    for rule in rules.split(', '):
        field, order = rule.split()
        rules_dict[field] = {'name': field, 'order': order}
    return rules_dict

def apply_rules_and_sort(table, rules_dict):
