        nonlocal rules_dict
        for field in rules_dict.keys():
            if field in row:
                virtual_key = 1 << (ord(rules_dict[field]['name'][0]) - ord('A'))
                row[virtual_key] = row[field]
                del row[field]

    def sort_field(row):
        nonlocal rules_dict
        for field, rule in sorted(rules_dict.items()):
            if field in row:
                if row[field].startswith(str(rule['order'])):
                    row[virtual_key] = 1 << (ord(rule['name'][0]) - ord('A'))
                    return row[virtual_key]
        return 0

    global virtual_key
    rows = {-1: []}
    virtual_key = 0
    for row in table:
        has_virtual_key(row)
        virtual_key |= sort_field(row)
        rows[sort_field(row)].append(row)
    return rows

