import sys

def lex_comb(s, q, queries):
    ans = [-1] * q
    for l, r, x in queries:
        count = {}
        smaller = 0
        for w in set(s[l-1:r]):
            count[w] = 0
        for i in range(r-l+1):
            tmp = x
            if tmp not in count:
                count[x] = 0
            while y := s[i+(len(tmp)-r+1):i+len(tmp)+1]:
                if y > x:
                    ans[l-1] = y
                smaller += 1
                x = y
        for i in range(smaller, r-l+1):
            if x := s[l-1:i+1]:
