import math
from collections import deque

def bfs(tree, start, end):
    queue = [start]
    distances = {start: 0}
    visited = set([start])
    while queue:
        node = queue.pop(0)
        for neighbor in tree[node]:
            if neighbor not in visited:
                distances[neighbor] = distances[node] + 1
                queue.append(neighbor)
                visited.add(neighbor)
    return distances[end]

def calculate_spacings(end, distances, tree):
    edges = []
    leverages = []
    for neighbor in tree.get(end, []):
        if dist := bfs(tree, end, neighbor):
            distances[neighbor] += dist
            if distances[end] == -1:
                continue
            leverages.append(1.0 - (distances[end] + distances[neighbor] + 1) / len(tree[end]))
        next_leverage = (len(tree[end]) - dist + 2 - (len(tree[neighbor]) * 2)) / (len(tree[neighbor]) - 2) if tree[neighbor] else float("inf")
        if next_leverage < 0:
            next_leverage = float("inf")
        leverages.append(next_leverage)
        edges.append([neighbor + end, 1])
    leverages.append(0)
    edges.append([-end, 1])
    return edges, leverages

def preferred_paths(distances, tree, node, dist_rank):
    start_dist = distances[node]
    max_spacings = []
    for neighbor, dist in distances.items():
        levers, levers_sparse = calculate_spacings(neighbor, {neighbor: dist}, tree)
        max_lever = max(levers_sparse if 1 not in levers_sparse else levers, default=-math.inf)
        max_spacings.append((-max_spacings[0] - start_dist - dist, levers, levers_sparse))
    max_spacings.sort(reverse=True)
    return max_spacings

