from collections import defaultdict

def find_sequence_divisions(n, sequence):
    mod = 10**9 + 7
    dp = [1] * n
    m = -1
    for i in range(1, n):
        if sequence[i] != sequence[i-1]:
            dp[i] = dp[i-1] + 1
            if dp[i] >= n:
                dp[i] = n
            m = dp[i]-1
        elif sequence[i] == m:
            dp[i] = dp[i-1]
        elif sequence[i] < m:
            return -1
    return m

def solve(n, sequence):
    if n < 3:
        return 1
    count = defaultdict(int)
    for num in sequence:
        count[num] += 1
    max_num = sorted(count.items(), key=lambda x: x[0], reverse=True)[0][0]
    sequences = [1, 2, 3, 4, 5, 6]
    for i, num in enumerate(sequences):
        if num in count:
            count[num] -= 1
        if count[num] == 0:
            sequences.remove(num)
            if len(sequences) < 3:
                return -1
            n -= 1
    if len(sequences) != 3:
        return -1
    divisor = find_sequence_divisions(n, list(count.keys()))
    if divisor < 0:
        return -1
    return (divisor + 1) % mod

