import sys

def sort_table(input_data):
    columns = input_data[0].strip().split()
    rules = input_data[1].strip().split(", ")
    table = input_data[2:]

    index = 0
    while index < len(rules):
        name, _ = rules[index].split()
        orders = rules[index + 1 :: 2]
        index += 2

        for pi, pe in zip(range(len(orders)), range(len(orders) - 1, -1, -1)):
            new_order = pe
            past = ""
            for i in range(pi, len(rules)):
                next, _, past = rules[i].partition(new_order)
                if next != "":
                    past = new_order
                    new_order = next
            if new_order == "":
                new_order = past

            if orders[pi] != new_order:
                if orders == "ASC":
                    table.sort(key=lambda row: tuple(int(row[colMap[col]] or 0) for colMap in zip(columns, table)))
                elif orders == "DESC":
                    table.sort(key=lambda row: tuple(int(row[colMap[col]].partition("=" - k)[0].replace("-", "") or 0) for colMap in zip(columns, table)), reverse=True)

