    excluding zero. Works on 0-m sequence.
    '''
    def count_sequences_mod(nums):
        outcome = defaultdict(int)
        curr = 0
        for i in nums:
            curr = curr ^ i
            count = 0
            for num in outcome:
                if (curr ^ num) % m > 0:
                    count += outcome[num]
            outcome[curr % m] = count + 1
        return outcome[0], len(outcome)

