import sys

def calculate_time(x1, y1, x2, y2, speed, steps):
    cycle_time = y2 - x1
    energy_needed = speed * cycle_time
    if steps < 0:
        energy_needed -= steps
    elif steps > 0:
        energy_needed += steps

    final_speed = speed * (steps + 1) + 1 - (steps * (1 - 3 * speed))
    final_complete_cycles = steps // (1 - 3 * speed)
    final_remaining_cycles = steps % (1 - 3 * speed)
    final_cycle_time = y2 - x1
    final_energy = final_speed * final_cycle_time

    if steps > 0:
        final_energy -= energy_needed
    elif energy_needed > steps:
        final_energy += energy_needed

    if final_energy < 0:
        final_energy = 0

    return final_energy

def find_winner(n, L, walkways):
    low, high = 0, sys.float_info.max
    while high - low > 0.000001:
        middle = (low + high) / 2
        total_energy = 0
        for x1, y1, speed in walkways:
            if middle <= 1:
                total_energy += calculate_time(x1, y1, x1, y1, speed, middle)
            else:
                final_speed = speed * (middle + 1) + 1 - (middle * (1 - 3 * speed))
                if final_speed >= 0:
                    total_energy += 1 - (final_speed * (middle - 1) + (final_speed - 1) * (middle))
        if total_energy < 0:
            high = middle
        else:
            low = middle
    return low

