    cost_table = [[float('inf')] * (N + 1) for _ in range(K + 1)]
    for alliance in range(K + 1):
        cost = sum(teleport_costs[group_table[i % (K + 1)][i]] for i in range(len(group_table[i % (K + 1)])))
        cost_table[alliance][0] = cost

    # Floyd-Warshall algorithm to find minimum costs in graph
    for med in range(K + 1):
        for src in range(K + 1):
            for dest in range(K + 1):
                if cost_table[src][med] + cost_table[med][dest] < cost_table[src][dest]:
                    cost_table[src][dest] = cost_table[src][med] + cost_table[med][dest]

    # Cost graph from the base station to all planets
    cost_graph = defaultdict(list)
    base_cost = 0
    for alliance in range(K + 1):
        for i in group_table[alliance % (K + 1)]:
            base_cost += teleport_costs[alliance]
            for city in range(1, alliances[i] + 1):
                cost_graph[i].append([city, cost_table[alliance][city]])

    # Compute minimum cost from base station to each city
    result = [sys.maxsize] * (N + 1)
    result[S] = base_cost
    queue = deque([S])
    while queue:
        city = queue.popleft()
        for neighbor, cost in cost_graph[city]:
            if result[city] + cost < result[neighbor]:
                result[neighbor] = result[city] + cost
                queue.append(neighbor)

    # Return the result
    return ' '.join(map(str, result[1:]))

